// src/content/load-environment.ts — the per-environment prop layer, as data.
//
// Mirrors `load-level.ts` exactly, including the glob: `content/environments/
// *.json` is generated by `tools/extract/props.mjs` and is the ONLY description
// of where scenery goes. One file per environment, not per mission — thirteen
// missions share four environments and duplicating 6,000 trees thirteen times
// would be an architecture bug (rule 6).

import { globIds } from './glob-tree'

const modules = import.meta.glob<{ default: EnvironmentProps }>('/content/environments/*.json')

const pathFor = (id: string): string => `/content/environments/${id}.json`

export const environmentIds = (): string[] => globIds(modules, '/content/environments/')

/** The transform of the mesh INSIDE a prop prefab, relative to its root. */
export interface MeshTransform {
  /** Unity space. */
  readonly position: readonly number[]
  /** Unity space, xyzw. */
  readonly rotation: readonly number[]
  readonly scale: readonly number[]
}

export interface PropPaletteEntry {
  readonly prefab: string | null
  readonly mesh: string | null
  /** Bucket path, e.g. `assets/props/tree1.glb`. Null when unresolved. */
  readonly meshAsset: string | null
  readonly origin: string
  readonly licence: string
  /**
   * What the prop IS, classified by the pack it came from — `tree`, `cactus`,
   * `bush`, `palm`. The key `edition.props.scale` is looked up by (DEV-134), so
   * a preset can say "trees at 0.6" without naming a mesh. Absent on a palette
   * entry the extractor could not classify.
   */
  readonly kind?: string
  /**
   * What cancels the bake. `GenerateObjects()` overrides only the prefab ROOT,
   * so this subtree transform survives into every placed instance — and for the
   * Tree Pack bakes it is the difference between a tree and a 25x17x50 m mesh
   * sitting 286 m from its own placement point.
   */
  readonly meshTransform: MeshTransform | null
}

/** A `scatter[]` entry's placements, packed by `tools/assets/bake-placements.mjs`. */
export interface BakedPlacements {
  readonly count: number
  /**
   * How many the spawn clearing took out of this generator's draw (DEV-100).
   *
   * A receipt, not an input: `count` is already the post-clearing figure and
   * nothing at runtime reads this. It is here so that "the forest thinned" and
   * "the bake is stale" are distinguishable without re-running the tool.
   */
  readonly clearedBySpawnClearing?: number
  /** Map dimensions AFTER Unity's nPOT rescale — the grid the texels index. */
  readonly mapWidth: number
  readonly mapHeight: number
  /** The seed this was drawn with: `1 + index * 7919`, recorded not implied. */
  readonly seed: number
  readonly stride: number
  /** base64 of `count * stride` bytes. */
  readonly data: string
}

export interface PropScatter {
  readonly index: number
  /**
   * The legacy source path of the density map — the extraction receipt, and
   * the only record of where these placements came from. It is NOT fetched.
   */
  readonly placementMap: string
  /**
   * The scatter, already run. See `sim/props/placements.ts`.
   *
   * There is no `placementMapAsset` any more and that is the point: the World
   * Machine density maps are content, not game assets, so they are no longer
   * published and the browser never asks for one. Matt's call, 2026-09-13.
   */
  readonly placements: BakedPlacements
  /**
   * What the 2016 source file holds for this pass — the component's own
   * `_StoredChunks` output list, resolved. `bakedObjects: 0` is a pass the
   * shipped 2016 build never drew: alpine's big-tree pass (also `m_Enabled: 0`),
   * simonet's and kauai's palms. The runtime does not consult it; whether those
   * passes stay is DEV-102, and `tests/unit/props-2016-bake.test.ts` keeps the
   * receipt honest against the file in the meantime.
   */
  readonly shipped2016?: {
    readonly componentEnabled: boolean
    readonly bakedObjects: number
    readonly note: string
  }
  readonly probabilityScale: number
  /** SUBTRACTED from the sampled height; alpine's -1 and -2.6 RAISE the props. */
  readonly heightOffset: number
  readonly scaleMin: number
  readonly scaleMax: number
  readonly lodDistance: number
  readonly lodTransitionTime: number
  readonly flipFlopPercent: number
  /** ORDERED, DUPLICATES INTACT — repetition is the weighting. */
  readonly palette: readonly PropPaletteEntry[]
}

/**
 * A hand-placed prop: desert's canyon spires, one spire on Simonet, and the
 * palms and big rock 2016 switched OFF. DEV-135.
 *
 * Transforms are COMPOSED down the parent chain to the environment root
 * (exclusive), in Unity space — the same frame the terrain's own transform is
 * given in, so `load-props.ts` subtracts that one transform to reach the
 * terrain's mesh frame and hangs the landmark under the terrain group like
 * every other prop. Until DEV-135 they were the mesh node's LOCAL transform,
 * which for the 26 AxeyWorks palms was `(0, 0, 0) x 1` under a `tree_palm_01`
 * that carried the real placement.
 */
export interface PropLandmark {
  readonly name: string
  readonly mesh: string
  /** Bucket path, e.g. `assets/props/spire-b.glb`. Null when unresolved. */
  readonly meshAsset?: string | null
  /**
   * `spire`, `rock`, `palm`, or whatever the extractor could tell from the pack.
   *
   * Nullable as well as optional since DEV-218: a mission's props carry the
   * environment vocabulary's own classification through verbatim, and that
   * emits an explicit `null` rather than dropping the key.
   */
  readonly kind?: string | null
  readonly origin: string
  readonly licence: string
  /**
   * Whether 2016 DREW it: `m_IsActive: 1` on the GameObject and on every
   * ancestor. Desert's `Spire_B_w_Collision (3)` is off; so is every palm under
   * `art/trees`, and the big rock under `MM_BigRock_collider`. Classic draws the
   * live ones only. Absent means the extractor predates the flag — treat as
   * unknown, which is NOT live.
   */
  readonly live?: boolean
  /** The chain of GameObject names from the environment root, for a reader. */
  readonly path?: string
  readonly position: readonly number[]
  readonly rotation: readonly number[] | null
  readonly scale: readonly number[] | null
}

/**
 * The ground every generator here left alone, and why (DEV-100).
 *
 * A RECEIPT for the blobs: the clearing is already applied to every
 * `placements` blob under it, so the 2016 scatter never consults this at
 * runtime — but the radius and the centres are the whole of the deviation, and
 * a generated file that carries its blobs without carrying the premise they
 * were drawn under is a number with no provenance in a repo whose first rule
 * is that numbers have provenance.
 *
 * And since DEV-103 an INPUT for the Anniversary dressing:
 * `game/props/load-dressing.ts` reads it at boot so DEV-089's rocks and shrubs
 * leave alone exactly the ground the palms were baked to leave alone, off one
 * list rather than two derivations. A stale receipt would therefore clear the
 * wrong ground for the dressing, which is why `tests/unit/spawn-clearing.test.ts`
 * holds its centres to the level JSONs as well as sweeping the blobs.
 */
export interface SpawnClearing {
  /** Metres. Cylinders, unbounded in y — see `sim/props/clearing.ts`. */
  readonly radius: number
  readonly source: string
  readonly note: string
  /** Every mission of this environment, in the terrain's own mesh space. */
  readonly missions: readonly { readonly id: string; readonly x: number; readonly z: number }[]
}

export interface EnvironmentProps {
  readonly id: string
  readonly environmentScene: string
  readonly source: { readonly kind: string; readonly path: string }
  /** Absent only on an environment baked before DEV-100. */
  readonly spawnClearing?: SpawnClearing
  readonly scatter: readonly PropScatter[]
  readonly landmarks: readonly PropLandmark[]
  readonly landmarksConfidence?: string
}

export class EnvironmentNotFound extends Error {
  constructor(id: string) {
    super(`no environment '${id}' — have ${environmentIds().join(', ') || '(none)'}`)
    this.name = 'EnvironmentNotFound'
  }
}

/**
 * Load one environment's prop data, or `null` when it has none.
 *
 * Null rather than throwing: an environment with no scatter is a legitimate
 * state (WinterWonderland ships one generator whose palette is desert's, and
 * nothing says every future environment must have scenery). The caller draws
 * no props and carries on.
 */
export const loadEnvironmentProps = async (id: string): Promise<EnvironmentProps | null> => {
  const mod = modules[pathFor(id)]
  if (!mod) return null
  const loaded = await mod()
  return loaded.default
}

/** Throwing variant, for callers that know the environment must exist. */
export const requireEnvironmentProps = async (id: string): Promise<EnvironmentProps> => {
  const env = await loadEnvironmentProps(id)
  if (!env) throw new EnvironmentNotFound(id)
  return env
}
